["GOSSIP_OPTION_SPIRITGUIDE"] = "GOSSIP_OPTION_SPIRITGUIDE",
["Yes.  Give me the spell to summon the avatar."] = "Evet. Avatarı çağırmam için gereken büyüyü bana ver.",
["Tell me about the Elementals Deck."] = "Bana Elementaller Desteği [Elementals Deck] hakkında bilgi ver.",
["You are talking nonsense, mage. "] = "Saçmalıyorsun, büyücü.",
["Tell me about the Portals Deck."] = "Bana Portallar Desteği [Portals Deck] hakkında bilgi ver.",
["Tell me about the Beasts Deck."] = "Bana Canavarlar Desteği [Beasts Deck] hakkında bilgi ver.",
["Tell me more about these Darkmoon Cards."] = "Bana bu Karaay Kartları [Darkmoon Cards] hakkında daha fazla bilgi ver.",
["I seem to have misplaced the distiller, Mux.  Did I happen to leave it here?"] = "Arıtıcıyı kaybettim galiba Mux. Yanlışlıkla burada mı bıraktım?",
["Why have you done such horrible things?"] = "Neden böyle korkunç şeyler yaptın?",
