    ["Stop whining!"] = "Stop whining!",                                                                
    ["Clean this place up! We will not live in such squalor."] = "Clean this place up! We will not live in such squalor.",                             
    ["It's my way or the Gold Road.  Is that understood?"] = "It's my way or the Gold Road.  Is that understood?",                                     
